def _find_module(name, path=None):
    """An importlib reimplementation of imp.find_module (for our purposes)."""
    importlib.machinery.PathFinder.invalidate_caches()
    spec = importlib.machinery.PathFinder.find_spec(name, path)
    if spec is None:
        raise ImportError('No module named {name!r}'.format(name=name), name=name)
    if spec.loader is importlib.machinery.BuiltinImporter:
        return (None, None, ('', '', _C_BUILTIN))
    if spec.loader is importlib.machinery.FrozenImporter:
        return (None, None, ('', '', _PY_FROZEN))
    file_path = spec.origin
    if spec.loader.is_package(name):
        return (None, os.path.dirname(file_path), ('', '', _PKG_DIRECTORY))
    if isinstance(spec.loader, importlib.machinery.SourceFileLoader):
        kind = _PY_SOURCE
    elif isinstance(spec.loader, (importlib.machinery.ExtensionFileLoader, importlib.machinery.AppleFrameworkLoader)):
        kind = _C_EXTENSION
    elif isinstance(spec.loader, importlib.machinery.SourcelessFileLoader):
        kind = _PY_COMPILED
    else:
        return (None, None, ('', '', _SEARCH_ERROR))
    file = io.open_code(file_path)
    suffix = os.path.splitext(file_path)[-1]
    return (file, file_path, (suffix, 'rb', kind))

def _build_graph_for_future(future: futures.Future, *, limit: int | None=None) -> FutureCallGraph:
    if not isinstance(future, futures.Future):
        raise TypeError(f'{future!r} object does not appear to be compatible with asyncio.Future')
    coro = None
    if (get_coro := getattr(future, 'get_coro', None)):
        coro = get_coro() if limit != 0 else None
    st: list[FrameCallGraphEntry] = []
    awaited_by: list[FutureCallGraph] = []
    while coro is not None:
        if hasattr(coro, 'cr_await'):
            st.append(FrameCallGraphEntry(coro.cr_frame))
            coro = coro.cr_await
        elif hasattr(coro, 'ag_await'):
            st.append(FrameCallGraphEntry(coro.cr_frame))
            coro = coro.ag_await
        else:
            break
    if future._asyncio_awaited_by:
        for parent in future._asyncio_awaited_by:
            awaited_by.append(_build_graph_for_future(parent, limit=limit))
    if limit is not None:
        if limit > 0:
            st = st[:limit]
        elif limit < 0:
            st = st[limit:]
    st.reverse()
    return FutureCallGraph(future, tuple(st), tuple(awaited_by))

def _ellipsis_match(want, got):
    """
    Essentially the only subtle case:
    >>> _ellipsis_match('aa...aa', 'aaa')
    False
    """
    if ELLIPSIS_MARKER not in want:
        return want == got
    ws = want.split(ELLIPSIS_MARKER)
    assert len(ws) >= 2
    startpos, endpos = (0, len(got))
    w = ws[0]
    if w:
        if got.startswith(w):
            startpos = len(w)
            del ws[0]
        else:
            return False
    w = ws[-1]
    if w:
        if got.endswith(w):
            endpos -= len(w)
            del ws[-1]
        else:
            return False
    if startpos > endpos:
        return False
    for w in ws:
        startpos = got.find(w, startpos, endpos)
        if startpos < 0:
            return False
        startpos += len(w)
    return True

def find_function(funcname, filename):
    cre = re.compile('def\\s+%s(\\s*\\[.+\\])?\\s*[(]' % re.escape(funcname))
    try:
        fp = tokenize.open(filename)
    except OSError:
        lines = linecache.getlines(filename)
        if not lines:
            return None
        fp = io.StringIO(''.join(lines))
    funcdef = ''
    funcstart = 0
    with fp:
        for lineno, line in enumerate(fp, start=1):
            if cre.match(line):
                funcstart, funcdef = (lineno, line)
            elif funcdef:
                funcdef += line
            if funcdef:
                try:
                    code = compile(funcdef, filename, 'exec')
                except SyntaxError:
                    continue
                funccode = next((c for c in code.co_consts if isinstance(c, CodeType) and c.co_name == funcname))
                lineno_offset = find_first_executable_line(funccode)
                return (funcname, filename, funcstart + lineno_offset - 1)
    return None

