def _infer_return_type(*args):
    """Look at the type of all args and divine their implied return type."""
    return_type = None
    for arg in args:
        if arg is None:
            continue
        if isinstance(arg, _os.PathLike):
            arg = _os.fspath(arg)
        if isinstance(arg, bytes):
            if return_type is str:
                raise TypeError("Can't mix bytes and non-bytes in path components.")
            return_type = bytes
        else:
            if return_type is bytes:
                raise TypeError("Can't mix bytes and non-bytes in path components.")
            return_type = str
    if return_type is not None:
        if tempdir is None or isinstance(tempdir, str):
            return str
        else:
            return bytes
    return return_type

def ensure_different_files(source, target):
    """
    Raise OSError(EINVAL) if both paths refer to the same file.
    """
    try:
        source_file_id = source.info._file_id
        target_file_id = target.info._file_id
    except AttributeError:
        if source != target:
            return
    else:
        try:
            if source_file_id() != target_file_id():
                return
        except (OSError, ValueError):
            return
    err = OSError(EINVAL, 'Source and target are the same file')
    err.filename = str(source)
    err.filename2 = str(target)
    raise err

def parse_args():
    import argparse
    parser = argparse.ArgumentParser(usage='%(prog)s [-h] [-c command] (-m module | -p pid | pyfile) [args ...]', description=_usage, formatter_class=argparse.RawDescriptionHelpFormatter, allow_abbrev=False, color=True)
    parser.add_argument('-c', '--command', action='append', default=[], metavar='command', dest='commands', help='pdb commands to execute as if given in a .pdbrc file')
    opts, args = parser.parse_known_args()
    if not args:
        parser.add_argument('-m', metavar='module', dest='module')
        parser.add_argument('-p', '--pid', type=int, help='attach to the specified PID', default=None)
        parser.print_help()
        sys.exit(2)
    elif args[0] == '-p' or args[0] == '--pid':
        parser.add_argument('-p', '--pid', type=int, help='attach to the specified PID', default=None)
        opts, args = parser.parse_known_args()
        if args:
            parser.error(f"unrecognized arguments: {' '.join(args)}")
    elif args[0] == '-m':
        parser.add_argument('-m', metavar='module', dest='module')
        opt_module = parser.parse_args(args[:2])
        opts.module = opt_module.module
        args = args[2:]
    elif args[0] == '--':
        args.pop(0)
        if not args:
            parser.error('missing script or module to run')
    elif args[0].startswith('-'):
        invalid_args = list(itertools.takewhile(lambda a: a.startswith('-'), args))
        parser.error(f"unrecognized arguments: {' '.join(invalid_args)}")
    return (opts, args)

def _unmarshal_code(self, pathname, fullpath, fullname, data):
    exc_details = {'name': fullname, 'path': fullpath}
    flags = _bootstrap_external._classify_pyc(data, fullname, exc_details)
    hash_based = flags & 1 != 0
    if hash_based:
        check_source = flags & 2 != 0
        if _imp.check_hash_based_pycs != 'never' and (check_source or _imp.check_hash_based_pycs == 'always'):
            source_bytes = _get_pyc_source(self, fullpath)
            if source_bytes is not None:
                source_hash = _imp.source_hash(_imp.pyc_magic_number_token, source_bytes)
                _bootstrap_external._validate_hash_pyc(data, source_hash, fullname, exc_details)
    else:
        source_mtime, source_size = _get_mtime_and_size_of_source(self, fullpath)
        if source_mtime:
            if not _eq_mtime(_unpack_uint32(data[8:12]), source_mtime) or _unpack_uint32(data[12:16]) != source_size:
                _bootstrap._verbose_message(f'bytecode is stale for {fullname!r}')
                return None
    code = marshal.loads(data[16:])
    if not isinstance(code, _code_type):
        raise TypeError(f'compiled module {pathname!r} is not a code object')
    return code

