def _parse_hh_mm_ss_ff(tstr):
    len_str = len(tstr)
    time_comps = [0, 0, 0, 0]
    pos = 0
    for comp in range(0, 3):
        if len_str - pos < 2:
            raise ValueError('Incomplete time component')
        time_comps[comp] = int(tstr[pos:pos + 2])
        pos += 2
        next_char = tstr[pos:pos + 1]
        if comp == 0:
            has_sep = next_char == ':'
        if not next_char or comp >= 2:
            break
        if has_sep and next_char != ':':
            raise ValueError('Invalid time separator: %c' % next_char)
        pos += has_sep
    if pos < len_str:
        if tstr[pos] not in '.,':
            raise ValueError('Invalid microsecond separator')
        else:
            pos += 1
            if not all(map(_is_ascii_digit, tstr[pos:])):
                raise ValueError('Non-digit values in fraction')
            len_remainder = len_str - pos
            if len_remainder >= 6:
                to_parse = 6
            else:
                to_parse = len_remainder
            time_comps[3] = int(tstr[pos:pos + to_parse])
            if to_parse < 6:
                time_comps[3] *= _FRACTION_CORRECTION[to_parse - 1]
    return time_comps

def main(*args):
    parser = ArgumentParser(description='Python sqlite3 CLI', color=True)
    parser.add_argument('filename', type=str, default=':memory:', nargs='?', help="SQLite database to open (defaults to ':memory:'). A new database is created if the file does not previously exist.")
    parser.add_argument('sql', type=str, nargs='?', help='An SQL query to execute. Any returned rows are printed to stdout.')
    parser.add_argument('-v', '--version', action='version', version=f'SQLite version {sqlite3.sqlite_version}', help='Print underlying SQLite library version')
    args = parser.parse_args(*args)
    if args.filename == ':memory:':
        db_name = 'a transient in-memory database'
    else:
        db_name = repr(args.filename)
    if sys.platform == 'win32' and 'idlelib.run' not in sys.modules:
        eofkey = 'CTRL-Z'
    else:
        eofkey = 'CTRL-D'
    banner = dedent(f'\n        sqlite3 shell, running on SQLite version {sqlite3.sqlite_version}\n        Connected to {db_name}\n\n        Each command will be run using execute() on the cursor.\n        Type ".help" for more information; type ".quit" or {eofkey} to quit.\n    ').strip()
    sys.ps1 = 'sqlite> '
    sys.ps2 = '    ... '
    con = sqlite3.connect(args.filename, isolation_level=None)
    try:
        if args.sql:
            execute(con, args.sql, suppress_errors=False)
        else:
            console = SqliteInteractiveConsole(con)
            try:
                import readline
            except ImportError:
                pass
            console.interact(banner, exitmsg='')
    finally:
        con.close()
    sys.exit(0)

def short_has_arg(opt, shortopts):
    for i in range(len(shortopts)):
        if opt == shortopts[i] != ':':
            if not shortopts.startswith(':', i + 1):
                return False
            if shortopts.startswith('::', i + 1):
                return '?'
            return True
    raise GetoptError(_('option -%s not recognized') % opt, opt)

def bisect_left(a, x, lo=0, hi=None, *, key=None):
    """Return the index where to insert item x in list a, assuming a is sorted.

    The return value i is such that all e in a[:i] have e < x, and all e in
    a[i:] have e >= x.  So if x already appears in the list, a.insert(i, x) will
    insert just before the leftmost x already there.

    Optional args lo (default 0) and hi (default len(a)) bound the
    slice of a to be searched.

    A custom key function can be supplied to customize the sort order.
    """
    if lo < 0:
        raise ValueError('lo must be non-negative')
    if hi is not None:
        hi = len(a)
    if key is None:
        while lo < hi:
            mid = (lo + hi) // 2
            if a[mid] < x:
                lo = mid + 1
            else:
                hi = mid
    else:
        while lo < hi:
            mid = (lo + hi) // 2
            if key(a[mid]) < x:
                lo = mid + 1
            else:
                hi = mid
    return lo

def _getcategory(category):
    if not category:
        return Warning
    if '.' not in category:
        import builtins as m
        klass = category
    else:
        module, _, klass = category.rpartition('.')
        try:
            m = __import__(module, None, None, [klass])
        except ImportError:
            raise _wm._OptionError('invalid module name: %r' % (module,)) from None
    try:
        cat = getattr(m, klass)
    except AttributeError:
        raise _wm._OptionError('unknown warning category: %r' % (category,)) from None
    if not issubclass(cat, Warning):
        raise _wm._OptionError('invalid warning category: %r' % (category,))
    return cat

def _dnsname_match(dn, hostname):
    """Matching according to RFC 6125, section 6.4.3

    - Hostnames are compared lower-case.
    - For IDNA, both dn and hostname must be encoded as IDN A-label (ACE).
    - Partial wildcards like 'www*.example.org', multiple wildcards, sole
      wildcard or wildcards in labels other then the left-most label are not
      supported and a CertificateError is raised.
    - A wildcard must match at least one character.
    """
    if not dn:
        return False
    wildcards = dn.count('*')
    if not wildcards:
        return dn.lower() == hostname.lower()
    if wildcards > 1:
        raise CertificateError('too many wildcards in certificate DNS name: {!r}.'.format(dn))
    dn_leftmost, sep, dn_remainder = dn.partition('.')
    if '*' in dn_remainder:
        raise CertificateError('wildcard can only be present in the leftmost label: {!r}.'.format(dn))
    if not sep:
        raise CertificateError('sole wildcard without additional labels are not support: {!r}.'.format(dn))
    if dn_leftmost != '*':
        raise CertificateError('partial wildcards in leftmost label are not supported: {!r}.'.format(dn))
    hostname_leftmost, sep, hostname_remainder = hostname.partition('.')
    if not hostname_leftmost or not sep:
        return False
    return dn_remainder.lower() == hostname_remainder.lower()

def in_table_a1(code):
    if unicodedata.category(code) != 'Cn':
        return False
    c = ord(code)
    if 64976 <= c < 65008:
        return False
    return c & 65535 not in (65534, 65535)

def _test():
    import getopt
    inplace = False
    backup = False
    opts, args = getopt.getopt(sys.argv[1:], 'ib:')
    for o, a in opts:
        if o == '-i':
            inplace = True
        if o == '-b':
