def _check_name(method):
    """Decorator to verify that the module being requested matches the one the
    loader can handle.

    The first argument (self) must define _name which the second argument is
    compared against. If the comparison fails then ImportError is raised.

    """

    def _check_name_wrapper(self, name=None, *args, **kwargs):
        if name is None:
            name = self.name
        elif self.name != name:
            raise ImportError('loader for %s cannot handle %s' % (self.name, name), name=name)
        return method(self, name, *args, **kwargs)
    if _bootstrap is not None:
        _wrap = _bootstrap._wrap
    else:

        def _wrap(new, old):
            for replace in ['__module__', '__name__', '__qualname__', '__doc__']:
                if hasattr(old, replace):
                    setattr(new, replace, getattr(old, replace))
            new.__dict__.update(old.__dict__)
    _wrap(_check_name_wrapper, method)
    return _check_name_wrapper

def mktime_tz(data):
    """Turn a 10-tuple as returned by parsedate_tz() into a POSIX timestamp."""
    if data[9] is None:
        return time.mktime(data[:8] + (-1,))
    else:
        import calendar
        t = calendar.timegm(data)
        return t - data[9]

def ToUnicode(label):
    if len(label) > 1024:
        if isinstance(label, str):
            label = label.encode('utf-8', errors='backslashreplace')
        raise UnicodeDecodeError('idna', label, 0, len(label), 'label way too long')
    if isinstance(label, bytes):
        pure_ascii = True
    else:
        try:
            label = label.encode('ascii')
            pure_ascii = True
        except UnicodeEncodeError:
            pure_ascii = False
    if not pure_ascii:
        assert isinstance(label, str)
        label = nameprep(label)
        try:
            label = label.encode('ascii')
        except UnicodeEncodeError as exc:
            raise UnicodeEncodeError('idna', label, exc.start, exc.end, 'Invalid character in IDN label')
    assert isinstance(label, bytes)
    if not label.lower().startswith(ace_prefix):
        return str(label, 'ascii')
    label1 = label[len(ace_prefix):]
    try:
        result = label1.decode('punycode')
    except UnicodeDecodeError as exc:
        offset = len(ace_prefix)
        raise UnicodeDecodeError('idna', label, offset + exc.start, offset + exc.end, exc.reason)
    label2 = ToASCII(result)
    if str(label, 'ascii').lower() != str(label2, 'ascii'):
        raise UnicodeDecodeError('idna', label, 0, len(label), f"IDNA does not round-trip, '{label!r}' != '{label2!r}'")
    return result

