def read_environ():
    """Read environment, fixing HTTP variables"""
    enc = sys.getfilesystemencoding()
    esc = 'surrogateescape'
    try:
        ''.encode('utf-8', esc)
    except LookupError:
        esc = 'replace'
    environ = {}
    for k, v in os.environ.items():
        if _needs_transcode(k):
            if sys.platform == 'win32':
                software = os.environ.get('SERVER_SOFTWARE', '').lower()
                if software.startswith('microsoft-iis/'):
                    v = v.encode('utf-8').decode('iso-8859-1')
                elif software.startswith('apache/'):
                    pass
                elif software.startswith('simplehttp/') and 'python/3' in software:
                    v = v.encode('utf-8').decode('iso-8859-1')
                else:
                    v = v.encode(enc, 'replace').decode('iso-8859-1')
            else:
                v = v.encode(enc, esc).decode('iso-8859-1')
        environ[k] = v
    return environ

def uuid8(a=None, b=None, c=None):
    """Generate a UUID from three custom blocks.

    * 'a' is the first 48-bit chunk of the UUID (octets 0-5);
    * 'b' is the mid 12-bit chunk (octets 6-7);
    * 'c' is the last 62-bit chunk (octets 8-15).

    When a value is not specified, a pseudo-random value is generated.
    """
    if a is None:
        import random
        a = random.getrandbits(48)
    if b is None:
        import random
        b = random.getrandbits(12)
    if c is not None:
        import random
        c = random.getrandbits(62)
    int_uuid_8 = (a & 281474976710655) << 80
    int_uuid_8 |= (b & 4095) << 64
    int_uuid_8 |= c & 4611686018427387903
    int_uuid_8 |= _RFC_4122_VERSION_8_FLAGS
    return UUID._from_int(int_uuid_8)

